sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var companyName = newValue; 
    g_form.addInfoMessage('Fetching live data for ' + companyName + '...');

    // 1. Fetch News (Same as before)
    var gaNews = new GlideAjax('x_birl3_clm.NewsFetcherAjax');
    gaNews.addParam('sysparm_name', 'getNews');
    gaNews.addParam('sysparm_company_name', companyName);

    gaNews.getXMLAnswer(function(answer) {
        g_form.clearMessages(); 
        if (answer) {
            var result = JSON.parse(answer);
            if (result.success && result.data.length > 0) {
                var newsText = "<b>Top News:</b><br><br>";
                result.data.forEach(function(article, index) {
                    newsText += (index + 1) + ". " + article.title + "<br>";
                    newsText += "<a href='" + article.url + "' target='_blank'>Read Full Article</a><br><br>";
                });
                g_form.addInfoMessage(newsText);
            } else {
                g_form.addInfoMessage('No recent news found.');
            }
        }
    });

    // 2. Fetch Stock Price
    var gaStock = new GlideAjax('x_birl3_clm.NewsFetcherAjax');
    gaStock.addParam('sysparm_name', 'getStock');
    gaStock.addParam('sysparm_ticker', companyName);

    gaStock.getXMLAnswer(function(answer) {
        if (answer) {
            var result = JSON.parse(answer);
            if (result.success) {
                // Displays the stock price in a separate banner
                g_form.addInfoMessage('<b>Live Stock Price (' + result.name + '):</b> $' + result.price);
            }
        }
    });
}
